WITH scored AS (SELECT *, RANK() OVER (PARTITION BY country ORDER BY rating NULLS FIRST) AS rating_rank, SUM(rating) OVER (PARTITION BY country ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_rating, PERCENT_RANK() OVER (ORDER BY rating DESC) AS rating_percent_rank, ROUND(rating / SUM(rating) OVER (PARTITION BY city), 4) AS rating_share, LAST_VALUE(city) IGNORE NULLS OVER (PARTITION BY city ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_city FROM suppliers) SELECT id, supplier_name, city, rating, cumulative_rating, rating_share, last_known_city, CASE WHEN supplier_name RLIKE '^(Siam Parts Co|EuroGoods GmbH)$' THEN 'CORE' ELSE 'PRIORITY' END AS supplier_name_zone FROM scored
